void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    for (i = 0; i < intf->cur_altsetting->desc.bNumEndpoints; i++) {
        struct usb_endpoint_descriptor *ep = &intf->cur_altsetting->endpoint[i].desc;
        printk(KERN_INFO "dvb-usb: disconnecting interface %d, endpoint %d\n",
               intf->cur_altsetting->desc.bInterfaceNumber, ep->bEndpointAddress);
    }

    if (d->props.exit) {
        d->props.exit(d);
    }

    dvb_usbv2_exit(d);
    printk(KERN_INFO "dvb-usb: successfully disconnected device\n");
    kfree(d->name);
}

void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    if (!d)
        return;

    for (i = 0; i < d->props.num_device_descs; i++)
        printk(KERN_INFO "DVB/USB: disconnecting interface %d\n", i);

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);
    printk(KERN_INFO "DVB/USB: successfully disconnected device\n");
    kfree(d->devname);
}

void dvb_usb_disconnect(struct usb_interface *intf)
{
    struct dvb_usb_device *d;

    if ((d = usb_get_intfdata(intf)) == NULL)
        return;

    dev_dbg(d->dev, "disconnected interface %d\n", intf->cur_altsetting->desc.bInterfaceNumber);

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);

    dev_info(d->dev, "DVB USB device %s successfully deinitialized and disconnected\n", d->name);
    kfree(d->name);
}

void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    if (!d)
        return;

    for (i = 0; i < d->num_adapters; i++) {
        struct dvb_adapter *adap = &d->adapters[i];
        if (adap->priv && adap->exit)
            adap->exit(adap);
    }

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);

    printk(KERN_INFO "DVB: USB %s disconnected\n", d->name);
    kfree(d->name);
    kfree(d);
}

void dvb_usb_disconnect(struct usb_interface *intf) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int i;

    if (!d)
        return;

    dev_info(&intf->dev, "DVB USB device disconnecting: interface %d\n", intf->altsetting->desc.bInterfaceNumber);

    if (d->props.exit)
        d->props.exit(d);

    dvb_usbv2_exit(d);

    dev_info(&intf->dev, "DVB USB device disconnected successfully.\n");

    kfree(d->name);
    kfree(d);
}
